"use client";

import { useState } from "react";
import { DeesserPanel } from "@/components/audio-ui/devices/deesser/panel";
import { useDeviceLoop } from "@/hooks/use-device-loop";
import { useMasterBus } from "@/hooks/use-master-bus";
import { useSpectrum } from "@/hooks/use-spectrum";
import {
  type DeesserState,
  deesserDevice,
} from "@/components/audio-ui/devices/deesser/device";
import { createDeesserEngine } from "@/components/audio-ui/devices/deesser/engine";

const MASTER_VOLUME = 0.7;
const MIN_HZ = 500;
const MAX_HZ = 20_000;

/**
 * A de-esser you can plug in: its state, a panel that draws what it does at
 * each frequency and an engine that plays it, each its own file and none
 * knowing the others. It plays a held vowel with an "s" on four beats: lower
 * the threshold and the s sits back, switch Listen on to hear the highs alone.
 */
export function BlockDeesser() {
  const [state, setState] = useState<DeesserState>(() =>
    deesserDevice.defaults()
  );
  const master = useMasterBus(MASTER_VOLUME);
  const { analyser } = useDeviceLoop({
    create: createDeesserEngine,
    destination: master,
    source: "voice",
    state,
  });
  const spectrum = useSpectrum(analyser, { maxHz: MAX_HZ, minHz: MIN_HZ });
  return (
    <div className="rounded-lg h-full w-full min-w-0">
      <DeesserPanel
        onValueChange={setState}
        spectrum={spectrum}
        value={state}
      />
    </div>
  );
}
